func (s *Store) UpsertSubscriptions(ctx context.Context, ss []Subscription) error {
	tx, err := s.DB.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	defer tx.Rollback()
	for _, x := range ss {
